import React, { useEffect, useState } from 'react';
import {
    Box, Typography, Container, Grid, Paper, Chip, Button, Link, Tabs, Tab, IconButton, Tooltip, useTheme
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import CheckIcon from '@mui/icons-material/Check';
import ScheduleIcon from '@mui/icons-material/Schedule';
import NotificationsActiveIcon from '@mui/icons-material/NotificationsActive';
import EventIcon from '@mui/icons-material/Event';
import ExploreIcon from '@mui/icons-material/Explore';
import TuneIcon from '@mui/icons-material/Tune';
import TravelExploreIcon from '@mui/icons-material/TravelExplore';
import LockOutlinedIcon from '@mui/icons-material/LockOutlined';
import SmartToyOutlinedIcon from '@mui/icons-material/SmartToyOutlined';

// AI Agents (2026-09-30): connect AI assistants to the Muslim Companion MCP
// server (public, read-only prayer data). Every step here was tested against
// the live server before publishing.

const MCP_URL = 'https://alexa.imuslimlife.com/v1/mcp';

const TOOLS = [
    { icon: <ScheduleIcon />, name: 'get_prayer_times', title: 'Prayer times for any day', text: 'Fajr, Sunrise, Dhuhr, Asr, Maghrib and Isha for a place and date, in local time, with the Hijri date.' },
    { icon: <NotificationsActiveIcon />, name: 'get_next_prayer', title: 'Next prayer', text: 'Which prayer is next, its time and how many minutes until it.' },
    { icon: <TravelExploreIcon />, name: 'find_location', title: 'Find a place', text: 'Turns a city or address into coordinates and a timezone.' },
    { icon: <EventIcon />, name: 'get_hijri_date', title: 'Hijri date', text: 'The Islamic date for any Gregorian date.' },
    { icon: <ExploreIcon />, name: 'get_qibla_direction', title: 'Qibla direction', text: 'Direction of the Kaaba from any place, in degrees and as a compass point.' },
    { icon: <TuneIcon />, name: 'list_calculation_methods', title: 'Calculation methods', text: 'ISNA, Muslim World League, Umm al-Qura, Karachi and 11 more, plus Hanafi or standard Asr.' },
];

const SETUPS = [
    {
        label: 'Claude',
        steps: [
            <>On <b>claude.ai</b> or in <b>Claude Desktop</b>, open <b>Settings → Connectors</b>.</>,
            <>Choose <b>Add custom connector</b>. Name it <b>Muslim Companion</b> and paste the server URL below.</>,
            <>Save. In a chat, turn the connector on (from the tools menu) and ask: <i>“When is Maghrib in Toronto today?”</i></>,
        ],
        code: MCP_URL,
        note: 'Custom connectors depend on your Claude plan. For Claude Code, run the command below instead.',
        code2: `claude mcp add --transport http muslim-companion ${MCP_URL}`,
    },
    {
        label: 'ChatGPT',
        steps: [
            <>In ChatGPT, open <b>Settings → Apps &amp; Connectors</b>, then <b>Advanced settings</b>, and turn on <b>Developer mode</b>.</>,
            <>Choose <b>Create</b> (new connector). Name it <b>Muslim Companion</b>, paste the server URL below, and choose <b>No authentication</b>.</>,
            <>In a new chat, add the connector and ask: <i>“What are today’s prayer times in London, Hanafi Asr?”</i></>,
        ],
        code: MCP_URL,
        note: 'Developer mode connectors depend on your ChatGPT plan, and menu names can change between versions.',
    },
    {
        label: 'Gemini CLI',
        steps: [
            <>Open <b>~/.gemini/settings.json</b> (create it if it doesn’t exist).</>,
            <>Add the <b>muslim-companion</b> entry below under <b>mcpServers</b>, then restart Gemini CLI.</>,
            <>Run <b>/mcp</b> to check it’s connected, then ask about prayer times.</>,
        ],
        code: JSON.stringify({ mcpServers: { 'muslim-companion': { httpUrl: MCP_URL } } }, null, 2),
    },
    {
        label: 'Copilot / VS Code',
        steps: [
            <>In your project, create <b>.vscode/mcp.json</b> (or run <b>MCP: Add Server</b> from the Command Palette and choose <b>HTTP</b>).</>,
            <>Paste the configuration below and click <b>Start</b> above the server entry.</>,
            <>In Copilot Chat, switch to <b>Agent</b> mode and ask about prayer times.</>,
        ],
        code: JSON.stringify({ servers: { 'muslim-companion': { type: 'http', url: MCP_URL } } }, null, 2),
    },
    {
        label: 'Developers',
        steps: [
            <>Any MCP client can connect: the server speaks <b>Streamable HTTP</b>, is stateless, and needs no API key.</>,
            <>Call a tool with a JSON-RPC <b>POST</b>, as in the example below.</>,
            <>Read <Link href="/llms.txt">llms.txt</Link> for a short overview written for language models.</>,
        ],
        code: `curl -s ${MCP_URL} \\\n  -H 'Content-Type: application/json' \\\n  -H 'Accept: application/json, text/event-stream' \\\n  -d '{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"get_prayer_times","arguments":{"latitude":43.6532,"longitude":-79.3832,"method":2}}}'`,
        note: 'Limits: 60 requests per minute and 600 per hour per client. Please cache a day’s times instead of asking repeatedly.',
    },
];

function CodeBlock({ text }) {
    const [copied, setCopied] = useState(false);
    const copy = () => {
        navigator.clipboard?.writeText(text).then(() => { setCopied(true); setTimeout(() => setCopied(false), 1800); }).catch(() => {});
    };
    return (
        <Box sx={{ position: 'relative', mt: 2, borderRadius: 2, bgcolor: '#0b1f1a', color: '#d1fae5', fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace', fontSize: { xs: '0.75rem', sm: '0.85rem' }, p: 2, pr: 6, whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
            {text}
            <Tooltip title={copied ? 'Copied' : 'Copy'}>
                <IconButton onClick={copy} size="small" aria-label="Copy" sx={{ position: 'absolute', top: 6, right: 6, color: '#a7f3d0' }}>
                    {copied ? <CheckIcon fontSize="small" /> : <ContentCopyIcon fontSize="small" />}
                </IconButton>
            </Tooltip>
        </Box>
    );
}

const AiAgentsPage = () => {
    const theme = useTheme();
    const [tab, setTab] = useState(0);
    useEffect(() => { window.scrollTo(0, 0); }, []);
    const s = SETUPS[tab];

    return (
        <>
            <Box sx={{ background: `linear-gradient(135deg, ${theme.palette.primary.main}, ${theme.palette.primary.dark})`, color: 'white', pt: 8, pb: 7 }}>
                <Container maxWidth="lg">
                    <Chip icon={<SmartToyOutlinedIcon sx={{ color: '#d1fae5 !important' }} />} label="New: MCP server" sx={{ mb: 2, bgcolor: 'rgba(255,255,255,0.15)', color: '#d1fae5', fontWeight: 700 }} />
                    <Typography variant="h2" component="h1" fontWeight={600} gutterBottom sx={{ fontSize: { xs: '2.2rem', md: '3.2rem' } }}>
                        Prayer times for your AI assistant
                    </Typography>
                    <Typography variant="h6" sx={{ opacity: 0.9, maxWidth: 760 }}>
                        Connect Claude, ChatGPT, Gemini or Copilot to the Muslim Companion prayer-times server. Your assistant then answers with real calculated times for your city and method, not a guess.
                    </Typography>
                    <CodeBlock text={MCP_URL} />
                </Container>
            </Box>

            <Container maxWidth="lg" sx={{ py: 8 }}>
                <Typography variant="h3" component="h2" align="center" gutterBottom sx={{ fontSize: { xs: '1.8rem', md: '2.4rem' } }}>What your assistant can do</Typography>
                <Typography align="center" color="text.secondary" sx={{ mb: 5, maxWidth: 720, mx: 'auto' }}>
                    Six read-only tools. Times are calculated for the place’s own timezone, with your choice of calculation method and Asr madhab.
                </Typography>
                <Grid container spacing={3}>
                    {TOOLS.map((t) => (
                        <Grid item xs={12} sm={6} md={4} key={t.name}>
                            <Paper variant="outlined" sx={{ p: 3, height: '100%', borderRadius: 3 }}>
                                <Box sx={{ color: theme.palette.primary.main, mb: 1 }}>{t.icon}</Box>
                                <Typography variant="h6">{t.title}</Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>{t.text}</Typography>
                                <Typography variant="caption" sx={{ fontFamily: 'monospace', opacity: 0.7, display: 'block', mt: 1 }}>{t.name}</Typography>
                            </Paper>
                        </Grid>
                    ))}
                </Grid>
            </Container>

            <Box sx={{ bgcolor: theme.palette.background.paper, py: 8 }}>
                <Container maxWidth="md">
                    <Typography variant="h3" component="h2" align="center" gutterBottom sx={{ fontSize: { xs: '1.8rem', md: '2.4rem' } }}>Set it up</Typography>
                    <Tabs value={tab} onChange={(_e, v) => setTab(v)} variant="scrollable" scrollButtons="auto" allowScrollButtonsMobile sx={{ mb: 3 }}>
                        {SETUPS.map((x) => <Tab key={x.label} label={x.label} />)}
                    </Tabs>
                    <Paper variant="outlined" sx={{ p: { xs: 2.5, sm: 4 }, borderRadius: 3 }}>
                        <Box component="ol" sx={{ pl: 3, m: 0, '& li': { mb: 1.5, lineHeight: 1.6 } }}>
                            {s.steps.map((step, i) => <li key={i}><Typography component="span">{step}</Typography></li>)}
                        </Box>
                        <CodeBlock text={s.code} />
                        {s.code2 && <CodeBlock text={s.code2} />}
                        {s.note && <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>{s.note}</Typography>}
                    </Paper>
                    <Typography variant="body2" color="text.secondary" sx={{ mt: 3 }}>
                        Try asking: <i>“When is Fajr tomorrow in Orlando?”</i> · <i>“Which way is the qibla from Karachi?”</i> · <i>“What is today’s Hijri date?”</i> · <i>“How long until Asr in Toronto, Hanafi?”</i>
                    </Typography>
                </Container>
            </Box>

            <Container maxWidth="md" sx={{ py: 8 }}>
                <Paper variant="outlined" sx={{ p: { xs: 3, sm: 4 }, borderRadius: 3, display: 'flex', gap: 2, alignItems: 'flex-start' }}>
                    <LockOutlinedIcon color="primary" sx={{ mt: 0.5 }} />
                    <Box>
                        <Typography variant="h6" gutterBottom>Public data only</Typography>
                        <Typography color="text.secondary">
                            The server only provides public information: prayer times, Hijri dates, qibla directions and calculation methods. It needs no account and cannot see or change anything in your Muslim Companion settings. Features that act for you, such as reading your own Athan schedule, will come later and will always require you to sign in and approve access. See our <Link href="/privacy-policy/">Privacy Policy</Link>.
                        </Typography>
                    </Box>
                </Paper>
                <Box sx={{ textAlign: 'center', mt: 5 }}>
                    <Button variant="contained" component={RouterLink} to="/alexa-skill" sx={{ borderRadius: 8, px: 4 }}>Muslim Companion for Alexa</Button>
                </Box>
            </Container>
        </>
    );
};

export default AiAgentsPage;
